                        {isVintage && (
                            <>
                                 <span 
                                    className="absolute left-1.5 font-serif font-bold text-[8px] text-[#5e4b35] opacity-80 tracking-widest z-20"
                                    style={{ top: '25%', transform: 'translateY(-50%)' }}
