                                 </span>
                                 <div 
                                    className="absolute w-full left-0 z-10 bg-[#3a2817] shadow-[inset_0_1px_3px_rgba(0,0,0,0.6)]"
                                    style={{ 
                                        height: `${grooveHeight}px`,
                                        borderRadius: '1px',
                                        opacity: 0.9,
                                        borderBottom: '1px solid rgba(255,255,255,0.2)'
                                    }}
