        </div>
      </div>

      {/* Fret Lines & Markers */}
      <div className="absolute top-0 bottom-0 right-0 left-0 pointer-events-none z-0">
        {fretLines.map((semitone) => {
          const percent = NUT_WIDTH_PERCENT + ((100 - NUT_WIDTH_PERCENT) * (semitone / semitoneRange));
