                    <>
                        <div className={`absolute w-full bg-cyan-400/30 blur-md transition-opacity duration-75 ${isVibrating ? 'opacity-100' : 'opacity-0'}`} style={{ height: `${thickness * 6}px` }}></div>
                        <div 
                            className="w-full"
                            style={{ 
                                height: `${thickness}px`,
