                ) : isNeon ? (
                    <>
                        <div className={`absolute w-full bg-purple-500/50 blur-md transition-opacity duration-75 ${isVibrating ? 'opacity-100' : 'opacity-0'}`} style={{ height: `${thickness * 8}px` }}></div>
                        <div 
                            className="w-full"
                            style={{ 
